import { useState } from "react";
import "./App.css";
import Viewer from "./components/Viewer";
import Controller from "./components/Controller";
import Even from "./components/Even";

function App() {
  // 1. State는 Viewer와 Controller의 공통 부모인 App에 만든다 (State 끌어올리기)
  const [count, setCount] = useState(0);

  // 2. 버튼 값만큼 count 변경
  const onClickButton = (value) => {
    setCount(count + value);
  };

  // 3. 0으로 초기화
  const onReset = () => {
    setCount(0);
  };

  return (
    <div className="App">
      <h1>Simple Counter</h1>
      <section>
        <Viewer count={count} />
        {count % 2 === 0 && <Even />}
      </section>
      <section>
        <Controller onClickButton={onClickButton} onReset={onReset} />
      </section>
    </div>
  );
}

export default App;

