import { useState } from "react";
import "./App.css";
import AmountInput from "./components/AmountInput";
import CurrencySelector from "./components/CurrencySelector";
import ConversionResult from "./components/ConversionResult";

// 1원(KRW)당 환율 (수정하지 마세요)
const RATES = {
  USD: 0.0007,
  EUR: 0.0006,
  JPY: 0.11,
};

function App() {
  const [amount, setAmount] = useState(1000);
  const [currency, setCurrency] = useState("USD");

  // 렌더링할 때마다 계산 → amount나 currency가 바뀌면 결과도 즉시 바뀜
  const result = (Number(amount) * RATES[currency]).toFixed(2);

  return (
    <div className="App">
      <section>
        <AmountInput amount={amount} onChangeAmount={setAmount} />
      </section>
      <section>
        <CurrencySelector onSelect={setCurrency} />
      </section>
      <section>
        <ConversionResult result={result} currency={currency} />
      </section>
    </div>
  );
}

export default App;

