import { useState } from "react";
import "./ExpenseEditor.css";

const ExpenseEditor = ({ onCreate }) => {
  const [description, setDescription] = useState("");
  const [amount, setAmount] = useState("");

  const onChangeDescription = (e) => {
    setDescription(e.target.value);
  };

  const onChangeAmount = (e) => {
    setAmount(e.target.value);
  };

  const onSubmit = (type) => {
    if (description === "" || amount === "" || Number(amount) <= 0) {
      return;
    }
    onCreate(type, description, Number(amount));
    setDescription("");
    setAmount("");
  };

  return (
    <div className="ExpenseEditor">
      <h4 className="editor_title">새 항목 추가하기</h4>
      <div className="editor_wrapper">
        <input
          type="text"
          className="desc_input"
          value={description}
          onChange={onChangeDescription}
          placeholder="내용을 입력하세요"
        />
        <input
          type="number"
          className="amount_input"
          value={amount}
          onChange={onChangeAmount}
          placeholder="금액"
        />
      </div>
      <div className="btn_wrapper">
        <button className="income_btn" onClick={() => onSubmit("income")}>
          수입 추가
        </button>
        <button className="expense_btn" onClick={() => onSubmit("expense")}>
          지출 추가
        </button>
      </div>
    </div>
  );
};

export default ExpenseEditor;

