import "./ExpenseSummary.css";

const ExpenseSummary = ({ list }) => {
  let income = 0;
  let expense = 0;
  list.forEach((it) => {
    if (it.type === "income") {
      income += it.amount;
    } else {
      expense += it.amount;
    }
  });
  const balance = income - expense;

  return (
    <div className="ExpenseSummary">
      <div className="summary_item income">
        <div className="label">총 수입</div>
        <div className="value">{income.toLocaleString()}원</div>
      </div>
      <div className="summary_item expense">
        <div className="label">총 지출</div>
        <div className="value">{expense.toLocaleString()}원</div>
      </div>
      <div className="summary_item balance">
        <div className="label">잔액</div>
        <div className="value">{balance.toLocaleString()}원</div>
      </div>
    </div>
  );
};

