import { useState, useRef } from "react";
import "./App.css";
import CardEditor from "./components/CardEditor";
import KanbanColumn from "./components/KanbanColumn";

// 컬럼 순서 (왼쪽 → 오른쪽). 수정하지 마세요.
const STATUSES = ["todo", "progress", "done"];

function App() {
  const [cards, setCards] = useState([]);
  const idRef = useRef(0);

  const onCreate = (title) => {
    const newCard = { id: idRef.current, title, status: "todo" };
    setCards([...cards, newCard]);
    idRef.current += 1;
  };

  const onMove = (targetId, direction) => {
    setCards(
      cards.map((card) => {
        if (card.id !== targetId) return card;
        const nextIndex = STATUSES.indexOf(card.status) + direction;
        if (nextIndex < 0 || nextIndex >= STATUSES.length) return card;
        return { ...card, status: STATUSES[nextIndex] };
      })
    );
  };

  return (
    <div className="App">
      <div className="header">
        <h2>미니 칸반 보드</h2>
      </div>
      <CardEditor onCreate={onCreate} />
      <div className="kanban-columns">
        <KanbanColumn
          title="Todo"
          cards={cards.filter((card) => card.status === "todo")}
          onMove={onMove}
        />
        <KanbanColumn
          title="In Progress"
          cards={cards.filter((card) => card.status === "progress")}
          onMove={onMove}
        />
        <KanbanColumn
          title="Done"
          cards={cards.filter((card) => card.status === "done")}
          onMove={onMove}
        />
      </div>
    </div>
  );
}

export default App;

